import{_ as a,o as t,c as s,a0 as i}from"./chunks/framework.C0WKPwzJ.js";const u=JSON.parse('{"title":"Install Autodevelop","description":"Install the Autodevelop Cursor plugin once at user scope, then sign in and bind a product repository.","frontmatter":{"title":"Install Autodevelop","description":"Install the Autodevelop Cursor plugin once at user scope, then sign in and bind a product repository."},"headers":[],"relativePath":"install.md","filePath":"install.md","lastUpdated":1788171427000}'),o={name:"install.md"};function n(p,e,r,l,h,d){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h1><p>Copyright (c) 2026 Devrecated.</p><p>Install Autodevelop <strong>once per machine</strong> as a <a href="https://cursor.com/docs/plugins.md" target="_blank" rel="noreferrer">Cursor Plugin</a>. Slash commands, rules, and hooks then load in every local workspace. Board ids, people, and mail settings stay in the <strong>consumer</strong> product repository.</p><p>How a team uses Autodevelop after install: <a href="./guide">Client guide</a>. Machine login: <a href="./cli">CLI</a>. GitHub: <a href="./github">GitHub App</a>.</p><h2 id="_1-import-the-plugin" tabindex="-1">1. Import the plugin <a class="header-anchor" href="#_1-import-the-plugin" aria-label="Permalink to &quot;1. Import the plugin&quot;">​</a></h2><p>From a checkout that has the kit, dry-run first:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> autodevelop:import</span></span></code></pre></div><p>If the list is right:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> autodevelop:import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span></code></pre></div><p>Reload Cursor (<strong>Developer: Reload Window</strong>). The same outcome is Customize → Install → <strong>user</strong>.</p><p>After the first apply, <code>/import-autodevelop</code> is available in Cursor.</p><p>Do not put <code>config.json</code>, <code>people.json</code>, or instance policies in the plugin. Those files belong in the consumer repo.</p><h2 id="_2-sign-in" tabindex="-1">2. Sign in <a class="header-anchor" href="#_2-sign-in" aria-label="Permalink to &quot;2. Sign in&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> autodevelop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span></code></pre></div><p>When the thin package is published, the same command is <code>npx @devprecated/autodevelop login</code>. The CLI opens a browser page with a device code. Approve this machine. A lapsed organization stops with <code>Your billing has expired</code>.</p><p>Paste the subscription token under <strong>Plugins → Configure</strong> if the operator issued one. Never commit it.</p><h2 id="_3-connect-github" tabindex="-1">3. Connect GitHub <a class="header-anchor" href="#_3-connect-github" aria-label="Permalink to &quot;3. Connect GitHub&quot;">​</a></h2><p>An operator with org management opens <strong>Connect GitHub</strong> in the operator console and installs the Autodevelop GitHub App. Steps: <a href="./github">GitHub App</a>.</p><h2 id="_4-bind-the-repository" tabindex="-1">4. Bind the repository <a class="header-anchor" href="#_4-bind-the-repository" aria-label="Permalink to &quot;4. Bind the repository&quot;">​</a></h2><p>In the consumer repo, add an instance folder and people. First-day sequence: <a href="./workflows/initial-setup">Initial setup</a>. Field names: <a href="./configure">Configure</a>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>Doctor never writes mail and never invents a confirm token.</p><h2 id="cloud-agents" tabindex="-1">Cloud Agents <a class="header-anchor" href="#cloud-agents" aria-label="Permalink to &quot;Cloud Agents&quot;">​</a></h2><p>Cloud Agents do not load user-scope plugins. Install the plugin at <strong>project</strong> scope in that workspace, or ask your operator for a workspace copy. Do not copy another organization’s instance folder.</p>',24)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
